//! Vectors for the strict parameter parser, generated by
//! `scripts/cpp_vectors/frame_parameters_vectors.cpp` from `fixtures/config/policy.txt`.
//!
//! Each line carries the mutated input (hex), the accepted flag, the rejection text (hex), every
//! parsed field, the eight groups' shapes and the whole `rest` (hex). The Rust parser must match
//! all of them, including the partial state that a rejection leaves behind.

use std::collections::HashMap;

use fp_core::frame::parameters::{read_parameters, GroupLine, Parameters, StageChoice};

const VECTORS: &str = include_str!("../../fixtures/frame_parameters_vectors.txt");

fn unhex(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    assert!(b.len() % 2 == 0, "odd hex length");
    let mut v = Vec::with_capacity(b.len() / 2);
    for p in b.chunks_exact(2) {
        v.push((hexval(p[0]) << 4) | hexval(p[1]));
    }
    v
}

fn hexval(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        _ => panic!("bad hex digit {}", c as char),
    }
}

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn group_str(g: &GroupLine) -> String {
    let mut s = format!("{},{},{},{}", g.log_n, g.log_ell, g.mask_log_n, g.mask_log_ell);
    for st in &g.stages {
        s.push_str(&format!(";{},{},{},{}", st.k, st.h, st.log_n, st.mask_log_n));
    }
    s
}

fn parse_group(s: &str) -> GroupLine {
    let mut parts = s.split(';');
    let head: Vec<u32> = parts
        .next()
        .unwrap()
        .split(',')
        .map(|x| x.parse().unwrap())
        .collect();
    let mut g = GroupLine {
        log_n: head[0],
        log_ell: head[1],
        mask_log_n: head[2],
        mask_log_ell: head[3],
        stages: Vec::new(),
    };
    for st in parts {
        let v: Vec<u32> = st.split(',').map(|x| x.parse().unwrap()).collect();
        g.stages.push(StageChoice { k: v[0], h: v[1], log_n: v[2], mask_log_n: v[3] });
    }
    g
}

fn p_u32(kv: &HashMap<&str, &str>, k: &str) -> u32 {
    kv[k].parse().unwrap()
}
fn p_u64(kv: &HashMap<&str, &str>, k: &str) -> u64 {
    kv[k].parse().unwrap()
}

fn check_line(line: &str) {
    let kv = fields(line);
    let name = kv["name"];
    let text = unhex(kv["input"]);
    let mut p = Parameters::default();
    let got = read_parameters(&text, &mut p);
    let why = if kv["why"] == "-" { String::new() } else { String::from_utf8(unhex(kv["why"])).unwrap() };
    match (kv["ok"], &got) {
        ("1", Ok(())) => assert!(why.is_empty(), "{}: an accepted parse has no rejection text", name),
        ("0", Err(e)) => assert_eq!(e, &why, "{}: rejection text", name),
        _ => panic!("{}: ok flag {} but parser returned {:?}", name, kv["ok"], got),
    }
    assert_eq!(p.version, u32::from_str_radix(kv["version"], 16).unwrap(), "{}: version", name);
    assert_eq!(p.sec, p_u32(&kv, "sec"), "{}: sec", name);
    assert_eq!(p.slots, p_u64(&kv, "slots"), "{}: slots", name);
    assert_eq!(p.answers, p_u32(&kv, "answers"), "{}: answers", name);
    assert_eq!(p.salt, p_u32(&kv, "salt"), "{}: salt", name);
    assert_eq!(p.ranges_part, p_u32(&kv, "ranges_part"), "{}: ranges_part", name);
    assert_eq!(p.table_rows_log, p_u32(&kv, "rows"), "{}: table rows", name);
    assert_eq!(p.table_log_n, p_u32(&kv, "n"), "{}: table n", name);
    assert_eq!(p.block_log, p_u32(&kv, "block"), "{}: block_log", name);
    assert_eq!(p.table_data, p_u64(&kv, "data"), "{}: table data", name);
    assert_eq!(p.table_random, p_u64(&kv, "random"), "{}: table random", name);
    let work: Vec<u32> = kv["work"].split(',').map(|x| x.parse().unwrap()).collect();
    for k in 0..5 {
        for s in 0..3 {
            assert_eq!(p.work[k][s], work[k * 3 + s], "{}: work[{}][{}]", name, k, s);
        }
    }
    let groups: Vec<&str> = kv["groups"].split('|').collect();
    assert_eq!(groups.len(), 8, "{}: eight groups", name);
    let got_groups = [
        &p.link, &p.folded, &p.omega, &p.own, &p.once_folded, &p.once_omega, &p.once_own,
        &p.once_ranges,
    ];
    for (i, g) in got_groups.iter().enumerate() {
        assert_eq!(group_str(g), groups[i], "{}: group {}", name, i);
        assert_eq!(*g, &parse_group(groups[i]), "{}: group {} stages", name, i);
    }
    assert_eq!(p.rest, unhex(kv["rest"]), "{}: rest", name);
}

#[test]
fn frame_parameters_match_the_cpp_reference() {
    let mut seen = 0usize;
    for line in VECTORS.lines() {
        if !line.starts_with("PARAM ") {
            continue;
        }
        check_line(line);
        seen += 1;
    }
    assert!(seen >= 40, "only {} parameter cases", seen);
}
